// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(bytes4 interfaceId) public {
        // General rule: whenever supportsInterface returns true for some id, the
        // core IERC1155 interface id (0xd9b67a26) MUST also be reported as
        // supported. C satisfies this for every fuzzed id (it always returns
        // true for the ERC1155 selector). The mutant dropped the IERC1155 check,
        // so supportsInterface(type(IERC1155).interfaceId) returns false there.
        bool supports = c.supportsInterface(interfaceId);
        assertTrue(!supports || c.supportsInterface(type(IERC1155).interfaceId));
    }
}

