pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface II165 { function supportsInterface(bytes4) external view returns (bool); }
interface II1155 {
    function balanceOf(address, uint256) external view returns (uint256);
    function balanceOfBatch(address[] calldata, uint256[] calldata) external view returns (uint256[] memory);
    function setApprovalForAll(address, bool) external;
    function isApprovedForAll(address, address) external view returns (bool);
    function safeTransferFrom(address, address, uint256, uint256, bytes calldata) external;
    function safeBatchTransferFrom(address, address, uint256[] calldata, uint256[] calldata, bytes calldata) external;
}

contract InvMutTest is Test {
    C c;
    bytes4 constant ERC165_ID = type(II165).interfaceId;
    bytes4 constant ERC1155_ID = type(II1155).interfaceId;
    bytes4 constant ERC1155_META_ID = ERC1155_ID ^ bytes4(keccak256("uri(uint256)"));

    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(bytes4 interfaceId) public {
        bool expected = interfaceId == ERC165_ID ||
                        interfaceId == ERC1155_ID ||
                        interfaceId == ERC1155_META_ID;
        bool ok = true;
        try c.supportsInterface(interfaceId) returns (bool supported) {
            ok = (supported == expected);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

