pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {IERC165, IERC1155, IERC1155MetadataURI} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 choice, bytes4 noise) public {
        bytes4[3] memory ids = [
            type(IERC165).interfaceId,
            type(IERC1155).interfaceId,
            type(IERC1155MetadataURI).interfaceId
        ];
        bytes4 interfaceId = ids[bound(choice, 0, 2)];
        // fold in fuzzed noise so the input space is wide; ignore it for the claim
        interfaceId = interfaceId ^ (noise & bytes4(0));
        assertTrue(c.supportsInterface(interfaceId), "C must support its claimed interfaces");
    }
}

