pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    bytes4 constant ERC165_ID = 0x01ffc9a7;
    bytes4 constant ERC1155_ID = 0xd9b67a26;

    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(uint256 seed) public {
        // Admissible domain: every possible bytes4 interface id.
        bytes4 interfaceId = bytes4(uint32(seed));

        // The metadata interface id, derived from its sole function selector
        // (interface id = XOR of all selectors; IERC1155MetadataURI has only uri(uint256)).
        bytes4 METADATA_ID = bytes4(keccak256("uri(uint256)"));

        bool result;
        try c.supportsInterface(interfaceId) returns (bool r) {
            result = r;
        } catch {
            result = false;
        }

        // General rule: supportsInterface reports true if and only if the id is one
        // of the three interfaces C declares support for (ERC165, IERC1155, IERC1155MetadataURI).
        bool expected = interfaceId == ERC165_ID || interfaceId == ERC1155_ID || interfaceId == METADATA_ID;
        assertTrue(result == expected);
    }
}

