pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(uint256 tokenId) public {
        // Rule: for ANY token id, C serves metadata through uri(uint256)
        // (public metadata surface), so ERC165 introspection must report
        // support for the IERC1155MetadataURI interface, whose selector is
        // derived from the very metadata function exposed: uri(uint256).
        string memory meta = c.uri(tokenId);
        bytes4 metadataSelector = bytes4(keccak256("uri(uint256)"));
        assertTrue(bytes(meta).length >= 0 && c.supportsInterface(metadataSelector));
    }
}

